    fn test_load_only_monitored_paths() {
        let toml_str = r#"monitored_paths = ['C:\Data\']"#;
        let config: AgentConfig = toml::from_str(toml_str).unwrap();
        assert_eq!(config.monitored_paths.len(), 1);
        assert!(config.excluded_paths.is_empty());
