            "user".into(),
            r"C:\Restricted\file.xlsx".into(),
            Classification::T4,
            Action::WRITE,
            Decision::DENY,
            "AGENT-001".into(),
            1,
        )
        .with_policy("pol-001".into(), "T4 Deny All".into())
        .with_justification("Business justification".into());

        let json = serde_json::to_string(&event).unwrap();
        let v: Value = parse_json(&json);

