        let mut cfg = AgentConfig {
            disk_allowlist: vec![disk_a.clone(), disk_b.clone()],
            ..Default::default()
        };
        // Seed the enumerator with both disks in instance_id_map.
        let enumerator = DiskEnumerator::new();
        {
            let mut map = enumerator.instance_id_map.write();
